function missingBetweenEnds(nums: number[]): number[] {
  const lo = Math.min(...nums), hi = Math.max(...nums);
  const out: number[] = [];
  for (let v = lo + 1; v < hi; v++) if (!nums.includes(v)) out.push(v);
  return out;
}

