function missingBetweenEnds(nums: number[]): number[] {
  let lo = Infinity, hi = -Infinity;
  for (const v of nums) {
    lo = Math.min(lo, v);
    hi = Math.max(hi, v);
  }
  const seen = new Set(nums);
  const out: number[] = [];
  for (let v = lo + 1; v < hi; v++) if (!seen.has(v)) out.push(v);
  return out;
}

